<?php
$o=$db->one('SELECT o.*,c.name owner_name,u.name preparer FROM customer_order o JOIN owner c ON c.id=o.owner_id LEFT JOIN user_account u ON u.id=o.preparer_id WHERE o.id=?',[(int)($_GET['id']??0)]);
$lines=$db->all('SELECT l.*,a.sku,a.name FROM order_line l JOIN article a ON a.id=l.article_id WHERE l.order_id=? ORDER BY l.id',[$o['id']]);
$picks=$db->all("SELECT p.*,a.sku,i.pallet_code,l.code lot,l.expires_on,e.code emplacement,COALESCE((SELECT SUM(qty) FROM package_pick WHERE pick_id=p.id),0) packed FROM pick p JOIN order_line ol ON ol.id=p.order_line_id JOIN article a ON a.id=ol.article_id JOIN receipt_item i ON i.id=p.receipt_item_id JOIN lot l ON l.id=i.lot_id JOIN location e ON e.id=p.location_id WHERE ol.order_id=? AND p.status<>'cancelled' ORDER BY p.id",[$o['id']]);
?>
<div class="page-heading"><div><p class="context">Commande et préparation</p><h1><?= h($o['reference']) ?></h1><p><?= h($o['owner_name'].' · '.$o['destination']) ?><br>Expédition souhaitée : <?= h($o['desired_on']) ?></p></div><?= badge($o['status']) ?></div>
<div class="actions"><a href="/?page=orders">Toutes les commandes</a><a href="<?= h(url(['page'=>'document','id'=>$o['id'],'kind'=>'pick'])) ?>">Liste de prélèvement</a><?php if($o['status']==='shipped'): ?><a href="<?= h(url(['page'=>'document','id'=>$o['id'],'kind'=>'delivery'])) ?>">Bon de livraison</a><a href="<?= h(url(['page'=>'document','id'=>$o['id'],'kind'=>'waybill'])) ?>">Lettre de voiture</a><?php endif; ?></div>
<?php if($o['revision_note']): ?><p>Dernière reprise : <?= h($o['revision_note']) ?></p><?php endif; ?>
<section class="panel"><h2>Articles commandés</h2><?php dataTable(array_map(fn($l)=>['Article'=>$l['sku'],'Désignation'=>$l['name'],'Quantité'=>$l['qty']],$lines)); ?>
<?php if($o['status']==='draft'): ?>
<?php startForm('save',['table'=>'order_line','order_id'=>$o['id']]);selectField('article_id','Article du propriétaire',$db->all('SELECT id,CONCAT(sku," / ",name) label FROM article WHERE owner_id=? ORDER BY sku',[$o['owner_id']]));inputField('qty','Quantité',1,'number'); ?><button>Ajouter un article</button></form>
<a href="<?= h(url(['page'=>'catalog','t'=>'order_line','f_order_id'=>$o['id']])) ?>">Modifier ou supprimer les lignes</a>
<?php startForm('prepare',['id'=>$o['id']],'inline-form');selectField('preparer_id','Préparateur',$db->all("SELECT id,name label FROM user_account WHERE active=1 AND role IN ('warehouse','manager','admin') ORDER BY name")); ?><button>Lancer la préparation FEFO</button></form>
<?php endif; ?></section>
<section class="panel"><h2>Prélèvements <?= $o['preparer']?'de '.h($o['preparer']):'' ?></h2><p>Chaque ligne conserve son lot et son emplacement d’origine.</p>
<?php foreach($picks as $p): ?><div class="receipt-summary"><div><strong><?= h($p['sku'].' · '.$p['lot'].' · '.$p['emplacement']) ?></strong><p><?= h($p['qty']) ?> unités · <?= h(Catalog::VALUES[$p['status']]) ?> · <?= h($p['packed']) ?> conditionnées</p></div>
<?php if($p['status']==='planned'&&($user['role']!=='warehouse'||$o['preparer_id']==$user['id'])){startForm('confirm_pick',['pick_id'=>$p['id']]); ?><button>Confirmer ce prélèvement</button></form><?php } ?></div><?php endforeach; ?>
<?php if(!$picks): ?><p class="empty">Aucun prélèvement actif.</p><?php endif; ?></section>
<section class="panel"><h2>Colis et palettes</h2>
<?php $packages=$db->all('SELECT * FROM package WHERE order_id=? ORDER BY id',[$o['id']]);foreach($packages as $pkg): ?><h3><?= h($pkg['code'].' · '.$pkg['type']) ?></h3><?php dataTable($db->all('SELECT a.sku article,l.code lot,pp.qty quantite FROM package_pick pp JOIN pick p ON p.id=pp.pick_id JOIN receipt_item i ON i.id=p.receipt_item_id JOIN lot l ON l.id=i.lot_id JOIN article a ON a.id=l.article_id WHERE pp.package_id=?',[$pkg['id']])); ?>
<?php if($o['status']==='ready'){startForm('save',['table'=>'package_pick','package_id'=>$pkg['id']],'inline-form');selectField('pick_id','Prélèvement à répartir',array_map(fn($p)=>['id'=>$p['id'],'label'=>$p['sku'].' / '.$p['lot'].' / '.$p['emplacement'].' : '.($p['qty']-$p['packed']).' unités restantes'],array_values(array_filter($picks,fn($p)=>$p['qty']>$p['packed']))));inputField('qty','Quantité dans ce colis',1,'number'); ?><button>Affecter cette quantité</button></form><?php } ?>
<?php endforeach;if(!$packages): ?><p class="empty">Aucun conditionnement créé.</p><?php endif; ?>
<?php if($o['status']==='ready'){startForm('save',['table'=>'package','order_id'=>$o['id']],'inline-form');inputField('code','Code de colis/palette');selectField('type','Conditionnement',[['id'=>'colis','label'=>'Colis'],['id'=>'palette','label'=>'Palette']]); ?><button>Créer le conditionnement</button></form><a href="<?= h(url(['page'=>'catalog','t'=>'package_pick'])) ?>">Corriger une allocation de colis</a><?php } ?></section>
<?php if($o['status']==='ready'): ?><section class="panel"><h2>Charger et expédier</h2><?php startForm('ship',['id'=>$o['id']]);selectField('visit_id','Camion sortant en chargement',$db->all("SELECT id,reference label FROM truck_visit WHERE status='working' AND operation='expedition' ORDER BY id DESC")); ?><button>Confirmer le chargement et l’expédition</button></form></section><?php endif; ?>
<?php if($o['status']!=='shipped'): ?><section class="panel"><h2>Corriger ou annuler</h2><p>La reprise libère les réservations, retire les conditionnements et conserve les anciens prélèvements comme annulés. La commande redevient modifiable.</p><?php startForm('reset_preparation',['id'=>$o['id']]);inputField('reason','Motif de reprise'); ?><button class="secondary" data-confirm="Reprendre en brouillon et retirer les allocations de colis ?">Reprendre en brouillon</button></form>
<?php if($o['status']!=='cancelled'){startForm('cancel_order',['id'=>$o['id']]); ?><button class="danger-link" data-confirm="Annuler cette commande ?">Annuler la commande</button></form><?php } ?></section><?php endif; ?>
